#!/bin/bash
# Builds Nunarchiver (or runs its tests: ./build.sh test), printing errors, warnings, and test results.
#
#   ./build.sh                    Debug build
#   CONFIG=Release ./build.sh     Release build (the app to measure: Build/Products/Release/Nunarchiver.app under $DD)
#   ./build.sh test               the tests
#
# Code coverage stays off: Xcode 27's autogenerated scheme instrumented every target, packages included, in Release
# too (the codecs' loops 3x longer, Xcode's xip minutes instead of seconds). The shared scheme turns it off;
# xcodebuild takes -enableCodeCoverage only when testing; and a built app with coverage counters fails here.
# Packages resolve with system git (TCA26 is private: the user's SSH key).
ROOT=$(cd "$(dirname "$0")" && pwd) || exit 2
CONFIG=${CONFIG:-Debug}
DD=${DD:-$ROOT/.build/DerivedData-$CONFIG}
LOG=${LOG:-$ROOT/.build/build-$CONFIG.log}
mkdir -p "$ROOT/.build" || exit 2
cd "$ROOT" || exit 2

coverage=()
[[ " $* " == *" test "* ]] && coverage=(-enableCodeCoverage NO)
xcodebuild -scmProvider system -project Nunarchiver.xcodeproj -scheme Nunarchiver -configuration "$CONFIG" \
  "${coverage[@]}" -derivedDataPath "$DD" -destination 'platform=macOS' "${@:-build}" > "$LOG" 2>&1
rc=$?
echo "exit $rc (log: $LOG)"
grep -E '(error|warning):' "$LOG" | grep -v appintentsmetadataprocessor | sort -u | head -60
grep -E '✔|✘' "$LOG" | head -30
[ $rc = 0 ] || exit $rc

APP="$DD/Build/Products/$CONFIG/Nunarchiver.app"
if [ -d "$APP" ]; then
  instrumented=0
  while IFS= read -r -d '' f; do
    if otool -l "$f" 2>/dev/null | grep -q '__llvm_prf_cnts'; then echo "COVERAGE COUNTERS in $f"; instrumented=1; fi
  done < <(find "$APP/Contents" -type f -perm -u+x -print0)
  [ $instrumented = 0 ] || exit 1
  echo "no coverage counters in $APP"
  # Building registers the app with LaunchServices, and "Open With" then picks any of the builds (a Debug one, once:
  # minutes for Xcode's archive). Builds are for launching by path: unregister this one.
  /System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister -u "$APP" > /dev/null 2>&1
fi
